import { chromium } from 'playwright';
const BASE='https://www.statesideqm.com',THEME='158561894555';
const routes=[['Accessories','/collections/accessories-gifts-collectibles'],['Airsoft','/collections/airsoft-milsim'],['Apparel','/collections/apparel'],['Armed Forces Gear','/collections/armed-forces-gear'],['Art','/collections/art'],['Body Armor','/collections/body-armor-ballistic-protection'],['Books','/collections/literature'],['Child Safety','/collections/child-safety-shop'],['DIVE / SCUBA','/collections/dive-scuba'],['Firearm Accessories','/collections/firearm-accessories'],['First Aid','/collections/first-aid-medical-ifak'],['Flags','/collections/flags-patriotic-decor'],['Flashlights','/collections/flashlights-lighting'],['Footwear','/collections/footwear-gloves-eyewear'],['K9','/collections/k9-dog-gear'],['Knives','/collections/knives-axes-cutlery'],['Morale Patches','/collections/morale-patches-tactical-id'],['Outdoor','/collections/outdoor-preparedness-gear'],['Patriotic','/collections/patriotic-american-heritage'],['Safety Rescue','/collections/safety-rescue-climbing'],['Sta-Brite','/collections/sta-brite-insignia'],['Tactical Gear','/collections/tactical-gear'],['Thin Line','/collections/thin-line'],['Uniforms','/collections/uniforms'],['Watches','/collections/watches'],['Lighters','/collections/zippos-lighters-torches'],['Logo Merch','/collections/stateside-quartermaster-logo-merch'],['Army National Guard','/collections/army-national-guard-series'],['Air National Guard','/collections/air-national-guard-series'],['U.S. Army','/collections/products-built-for-the-line-u-s-army'],['U.S. Navy','/collections/products-built-for-the-line-u-s-navy'],['U.S. Air Force','/collections/products-built-for-the-line-u-s-air-force'],['U.S. Marines','/collections/products-built-for-the-line-u-s-marine-corps'],['U.S. Coast Guard','/collections/products-built-for-the-line-u-s-coast-guard'],['U.S. Space Force','/collections/products-built-for-the-line-u-s-space-force'],['ROTC','/collections/rotc-series'],['JROTC','/collections/jrotc-series'],['Military Schools','/collections/military-schools-academies'],['Law Enforcement','/collections/law-enforcement-corrections'],['Fire EMS SAR','/collections/firefighting-ems-search-rescue']];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function preview(path){const u=new URL(path,BASE);u.searchParams.set('preview_theme_id',THEME);return u.toString()}
async function go(p,path){let last;for(let i=0;i<3;i++){try{const r=await p.goto(preview(path),{waitUntil:'domcontentloaded',timeout:60000});if(r?.status()===200){await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:30000});await sleep(1200);return}last=new Error('HTTP '+(r?.status()||0))}catch(e){last=e}await sleep([1500,3500,7000][i])}throw last}
async function snap(p){return p.evaluate(()=>{const m=document.querySelector('#MainContent');const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0};const sides=[...m.querySelectorAll('.sq-refine-v3-sidebar')].filter(vis);const legacy=[...m.querySelectorAll('.sq-global-refine-sidebar,.sq-collection-sidebar,.facets-block-wrapper,.facets-container,.facets-wrapper,[class*="filter-sidebar"]')].filter(e=>vis(e)&&!e.classList.contains('sq-refine-v3-sidebar'));const grids=[...m.querySelectorAll('.sq-refine-v3-results .product-grid')];const g=grids.find(x=>vis(x)&&[...x.querySelectorAll(':scope > .product-grid__item')].some(y=>vis(y)&&y.querySelector('a[href*="/products/"]')));const cards=g?[...g.querySelectorAll(':scope > .product-grid__item')].filter(x=>vis(x)&&x.querySelector('a[href*="/products/"]')):[];const rs=cards.slice(0,9).map(x=>x.getBoundingClientRect()),row=rs.length?rs.filter(r=>Math.abs(r.y-rs[0].y)<4).length:0;const s=sides[0],t=s?.querySelector('.sq-refine-v3-sidebar__title'),sr=s?.getBoundingClientRect(),tr=t?.getBoundingClientRect();const groups=s?[...s.querySelectorAll(':scope > details.sq-refine-v3-group')].filter(vis).map(d=>({label:(d.querySelector(':scope > summary')?.textContent||'').replace(/\s+/g,' ').trim(),inputs:d.querySelectorAll('input[type=checkbox]').length,targets:[...d.querySelectorAll('input[data-kind=structural][data-target]')].map(i=>i.dataset.target||'')})):[];return{v3:sides.length,legacy:legacy.length,title:(t?.textContent||'').trim(),titleBg:t?getComputedStyle(t).backgroundColor:'',sideBg:s?getComputedStyle(s).backgroundColor:'',gap:sr&&tr?Math.max(0,sr.right-tr.right):999,position:s?getComputedStyle(s).position:'',cards:cards.length,row,width:rs[0]?Math.round(rs[0].width):0,groups,pageSizes:[...m.querySelectorAll('.sq-refine-v3-page-size input')].map(i=>i.value)}})}
function errs(d,path){const e=[];if(d.v3!==1)e.push('sidebars='+d.v3);if(d.legacy)e.push('legacy='+d.legacy);if(d.title!=='REFINE PRODUCTS'||d.titleBg!=='rgb(8, 40, 63)'||d.sideBg!=='rgb(8, 40, 63)'||d.gap>1.5)e.push('header');if(d.position!=='sticky')e.push('position='+d.position);if(!d.cards)e.push('no products');if(d.row!==Math.min(3,d.cards))e.push('row='+d.row);if(d.cards>=3&&d.width<250)e.push('width='+d.width);if(d.pageSizes.join(',')!=='50,100,250')e.push('sizes='+d.pageSizes.join(','));for(const g of d.groups){if(!g.inputs)e.push('empty '+g.label);for(const x of g.targets){if(!x.startsWith('/collections/')||!new URL(x,BASE).searchParams.get('sq_root'))e.push('bad structural '+g.label)}}if(path==='/collections/literature'){const ls=d.groups.map(x=>x.label);for(const rx of [/publisher/i,/war|conflict|era/i,/branch|service/i,/topic|subject/i])if(!ls.some(x=>rx.test(x)))e.push('books '+rx);if(ls.some(x=>/author/i.test(x)))e.push('unsafe author')}if(path==='/collections/firearm-accessories'){const mm=d.groups.find(x=>/make\s*\/\s*model/i.test(x.label));if(!mm)e.push('missing Make/Model');else if(mm.inputs<1)e.push('empty Make/Model')}return e}
const browser=await chromium.launch({headless:true});const failures=[];let next=0;
async function worker(id){const ctx=await browser.newContext({viewport:{width:1440,height:1000}}),p=await ctx.newPage();while(true){const i=next++;if(i>=routes.length)break;const [name,path]=routes[i];try{await go(p,path);const d=await snap(p),e=errs(d,path);console.log((e.length?'FAIL ':'PASS ')+(i+1)+'/40 '+name+(e.length?' :: '+e.join(' | '):''));if(e.length)failures.push(name+': '+e.join(' | '))}catch(e){console.log('FAIL '+name+' :: '+e);failures.push(name+': '+e)}}await ctx.close()}
await Promise.all(Array.from({length:5},(_,i)=>worker(i)));
for(const [name,path] of [['State Guard','/collections/state-guard-series'],['Armored Vehicles','/pages/armored-vehicles-purchase-inquiry']]){const p=await browser.newPage({viewport:{width:1440,height:1000}});try{const r=await p.goto(preview(path),{waitUntil:'domcontentloaded',timeout:60000});await sleep(700);const x=await p.evaluate(()=>({v3:!!document.querySelector('[data-sq-refine-v3]'),side:!!document.querySelector('.sq-refine-v3-sidebar')}));if(r?.status()!==200||x.v3||x.side)failures.push(name+' protection '+JSON.stringify(x));console.log('PROTECTED '+name+' '+JSON.stringify(x))}catch(e){failures.push(name+': '+e)}await p.close()}
const mc=await browser.newContext({viewport:{width:390,height:844}}),mp=await mc.newPage();for(const path of ['/collections/apparel','/collections/literature','/collections/products-built-for-the-line-u-s-navy']){try{await go(mp,path);const d=await mp.evaluate(()=>{const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'};const s=[...document.querySelectorAll('.sq-refine-v3-sidebar')].filter(vis),g=[...document.querySelectorAll('.sq-refine-v3-results .product-grid')].find(vis),cards=g?[...g.querySelectorAll(':scope > .product-grid__item')].filter(vis).slice(0,6):[],rs=cards.map(x=>x.getBoundingClientRect()),row=rs.length?rs.filter(r=>Math.abs(r.y-rs[0].y)<4).length:0;return{sidebars:s.length,position:s[0]?getComputedStyle(s[0]).position:'',row,cards:cards.length}});console.log('MOBILE '+path+' '+JSON.stringify(d));if(d.sidebars!==1||d.position==='sticky'||d.row!==Math.min(2,d.cards)||d.cards<2)failures.push('mobile '+path+' '+JSON.stringify(d))}catch(e){failures.push('mobile '+path+': '+e)}}await mc.close();console.log('FAST-SUMMARY '+JSON.stringify({routes:40,failures:failures.length}));for(const f of failures)console.log('FAILURE '+f);await browser.close();if(failures.length)process.exit(1);
